import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Reinforcement Learning for LLM-based Multi-Agent Systems through Orchestration Traces","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.02801","title":"Reinforcement Learning for LLM-based Multi-Agent Systems through Orchestration Traces","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2605.02801,"authors":["Chenchen Zhang"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2605.02801v1","pdf_path":"pdfs/2605.02801.pdf","published_date":"2026-05-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-04-rl-multi-agent-orchestration-traces-2605-02801.md","filePath":"research/papers/2026-05-04-rl-multi-agent-orchestration-traces-2605-02801.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-05-04-rl-multi-agent-orchestration-traces-2605-02801.md"};function s(i,e,l,c,g,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="reinforcement-learning-for-llm-based-multi-agent-systems-through-orchestration-traces" tabindex="-1">Reinforcement Learning for LLM-based Multi-Agent Systems through Orchestration Traces <a class="header-anchor" href="#reinforcement-learning-for-llm-based-multi-agent-systems-through-orchestration-traces" aria-label="Permalink to &quot;Reinforcement Learning for LLM-based Multi-Agent Systems through Orchestration Traces&quot;">​</a></h1><p><strong>Authors</strong>: Chenchen Zhang <strong>Published</strong>: May 4, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2605.02801" target="_blank" rel="noreferrer">https://arxiv.org/abs/2605.02801</a> · <a href="https://arxiv.org/html/2605.02801v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2605.02801 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2605.02801" target="_blank" rel="noreferrer">research/papers/pdfs/2605.02801.pdf</a> (71 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>As large language model (LLM) agents evolve from isolated tool users into coordinated teams, reinforcement learning (RL) must optimize not only individual actions but also how work is spawned, delegated, communicated, aggregated, and stopped. This paper studies RL for LLM-based multi-agent systems through orchestration traces: temporal interaction graphs whose events include sub-agent spawning, delegation, communication, tool use, return, aggregation, and stopping decisions. Using this lens, we identify three technical axes. First, reward design spans eight families, including orchestration rewards for parallelism speedup, split correctness, and aggregation quality. Second, reward and credit signals attach to eight credit- or signal-bearing units from token to team; explicit counterfactual message-level credit remains especially sparse in our curated pool. Third, orchestration learning decomposes into five sub-decisions: when to spawn, whom to delegate to, how to communicate, how to aggregate, and when to stop. In our curated pool as of May 4, 2026, we found no explicit RL training method for the stopping decision. We connect academic methods to public industrial evidence from Kimi Agent Swarm, OpenAI Codex, and Anthropic Claude Code. The resulting scale gap is a gap between publicly reported deployment envelopes and open academic evaluation regimes, not independent verification of industrial training traces. We release the artifact at <a href="https://github.com/xxzcc/awesome-llm-mas-rl" target="_blank" rel="noreferrer">this https URL</a>, including an 84-entry tagged paper pool, a 32-record exclusion log, scripted corpus statistics, and a minimal JSON schema for replayable orchestration traces.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出以 <strong>orchestration traces</strong>（temporal interaction graphs）為統一視角研究 multi-agent RL，事件涵蓋 sub-agent spawning、delegation、communication、tool use、return、aggregation、stopping。</li><li>建立三條技術軸線：(1) <strong>reward design</strong> 分八大 family（含 parallelism speedup、split correctness、aggregation quality 等 orchestration reward）；(2) <strong>reward/credit signal</strong> 附著於八種 credit-bearing unit（從 token 到 team）；(3) <strong>orchestration learning</strong> 拆成五個 sub-decision：when to spawn / whom to delegate to / how to communicate / how to aggregate / when to stop。</li><li>系統性連結學術方法與工業界公開證據（Kimi Agent Swarm、OpenAI Codex、Anthropic Claude Code），並明確界定「scale gap」為<strong>部署規模 vs 學術評估規模的落差</strong>，而非對工業訓練 trace 的獨立驗證。</li><li>釋出可複現 artifact：84-entry tagged paper pool、32-record exclusion log、scripted corpus statistics、replayable orchestration trace 的 minimal JSON schema。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Curated pool（截至 2026-05-04）中，<strong>stopping decision 無任何 explicit RL training method</strong>——明確的 method-level gap。</li><li><strong>Message-level counterfactual credit</strong> 在 pool 中特別稀疏，屬 credit assignment 的開放難題。</li><li>量化 artifact 規模：84 篇 tagged paper、32 筆 exclusion record；本文偏 survey/taxonomy，量化結果以 corpus 統計與 gap 盤點為主，非 benchmark 性能數字。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未列明確 limitation 章節（基於 abstract 判讀）。可能弱點： <ul><li>單一 curated pool 偏 survey snapshot，<strong>時間敏感</strong>（作者自標 &quot;as of May 4, 2026&quot;），結論隨領域演進快速失效。</li><li>工業界證據為 public-reported，作者已自承<strong>非 independent verification</strong>，可能存在報導偏差。</li><li>84 篇 pool 規模對「跨八大 reward family × 八種 credit unit × 五 sub-decision」的覆蓋密度有限，部分 cell 可能僅單篇支撐。</li><li>單作者 survey，taxonomy 邊界與 inclusion/exclusion 判準的主觀性需以 exclusion log 自行覆核。</li></ul></li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>直接對應 The Loop / 自我演化主題</strong>：本文五個 orchestration sub-decision（spawn / delegate / communicate / aggregate / stop）與本 workspace 的 <code>core.md §PROPOSE 委派</code>（原 <code>subagent-strategy.md</code>）（Fan-out ≤4、parent↔child 通訊限制、handoff contract）是同構問題域——可作為「委派決策」規則的學術背書與盲點檢查清單。⚠️ 落地門檻：本文是 RL 訓練視角，workspace 規則是 prompt-time advisory，無訓練迴路，借鑑限於 taxonomy 而非方法移植。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li><strong>&quot;when to stop&quot; gap 值得內化</strong>：論文指出 stopping decision 無 explicit RL method，呼應 workspace 的 <code>self-escalate</code> / convergence verdict 設計——確定性 stop 條件（core.md 強成功條件）正是繞過此 gap 的工程解。⚠️ 本文未提供可直接套用的 stop 啟發式。</li><li><strong>orchestration trace 的 JSON schema</strong> 概念可對照 <code>claude-progress.json</code> / MEMORY 回路的事件記錄；replayable trace 思路或可啟發 overnight 任務的可觀測性設計。⚠️ schema 細節需讀 PDF/GitHub artifact 確認，abstract 僅述其存在。</li><li><strong>多 agent 矛盾治理</strong>：本文 aggregation quality reward 對應 workspace 「多 agent 輸出矛盾明列交主對話、child 不 self-resolve」的紀律；可評估是否將 aggregation 品質納入 fan-out 後的驗證 gate。⚠️ 屬概念連結，非現成實作。</li></ul>',16)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
